select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'CloudTalk AI Voice Agent' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Agent vocal IA de CloudTalk, téléphonie cloud slovaque, qui répond et passe des appels, qualifie les appelants, prend des rendez-vous et passe la main à l''équipe.',
  'AI voice agent from the Slovak cloud phone company CloudTalk that answers and makes calls, qualifies callers, books meetings and hands over to the team.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Smartsupp Mira AI' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
