select refresh_rankings();

select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('CloudTalk AI Voice Agent', 'Smartsupp Mira AI', 'Quo Sona', 'RingCentral AI Receptionist (AIR)', 'Sembly AI', 'SuperNinja', 'Simplified AI Agents', 'Tactiq', 'HyperWrite', 'Paxton', 'Valley', 'Topo') order by e.name;
